  ["65e15f65"] = "Принесіть предмет «{item:Libram of Protection}», 1 предмет «{item:Pristine Black Diamond}», «{item:Large Brilliant Shard}»: 2 шт. і 1 предмет «{item:Frayed Abomination Stitching}» НІП «{npc:Lorekeeper Lydros}» у підземеллі «{zone:Dire Maul}», щоб отримати предмет «{item:Arcanum of Protection}».",
  ["2c3e7ae6"] = "Зберіть «{item:Nordrassil Root Cap}»: 10 шт. у підземеллі «{zone:Blackmaw Hold}».",
  ["3e23bb96"] = "Здобудьте предмет «{item:Blackmaw Ritual Totem}» з одного з ворогів у підземеллі «{zone:Blackmaw Hold}».",
  ["883baf73"] = "Принесіть предмети «{item:Claws of the Great Bear}» і «{item:Tusks of the Unbroken}» до НІП «{npc:Ogtinc}» у локації «{zone:Azshara}».",
  ["3275e953"] = "Ці двоє ворогів ходять різними шляхами: пройдіть обидва.",
  ["e8aa7b9f"] = "Знайдіть власника предмета «{item:Feathered Charm Necklace}».",
  ["ca0ebee2"] = "Увійдіть у підземелля «{zone:Blackmaw Hold}» і здобудьте «{item:Blackmaw Pouch}»: 5 шт. для НІП біля «{zone:Ruins of Eldarath}» у локації «{zone:Azshara}».",
  ["89f0e428"] = "Потім цей НІП приймає ще торбинки як повторюване завдання («{zone:Timbermaw Hold}» +100).",
  ["b3b3a0f4"] = "Знайдіть предмети «{item:Totem of Ursoc}» і «{item:Totem of Ursol}» у підземеллі «{zone:Blackmaw Hold}». Потім поверніть їх до НІП у місцевості «{zone:Ursolan}».",
  ["74195c4a"] = "Принесіть голову ворога до НІП «{npc:Gatekeeper Rageroar}» у місцевості «{zone:Ursolan}».",
  ["88183d28"] = "Повторюване, після першої здачі торбинок.",
  ["1e691724"] = "Принесіть предмет «{item:Fel-Tainted Flesh}».",
  ["3a5728ae"] = "Поговоріть з НІП «{npc:Mathrengyl Bearwalker}» у місцевості «{zone:Cenarion Enclave}» у місті «{zone:Darnassus}».",
  ["f3c6e9b2"] = "Поговоріть з НІП «{npc:Nara Wildmane}» у місцевості «{zone:Elder Rise}» у місті «{zone:Thunder Bluff}».",
  ["bf3d943b"] = "Вирушайте до підземелля «{zone:Stratholme}» і знайдіть НІП «{npc:Archivist Galford}». Знищте його і спаліть архів.",
  ["773a0ce1"] = "Убийте боса «{npc:Archivist Galford}» у місцевості «{zone:The Scarlet Bastion}» і спаліть архіви.",
  ["d4819af9"] = "Віднесіть предмет «{item:Head of Balnazzar}» до НІП «{npc:Duke Nicholas Zverenhoff}» у локації «{zone:Eastern Plaguelands}».",
  ["2223cf7a"] = "Спершу здайте завдання «{quest:The Archivist}», інакше голова боса «{npc:Balnazzar}» не почне це завдання.",
  ["6418fa2c"] = "Здобудьте «{item:Plagued Flesh Sample}»: 20 шт. у підземеллі «{zone:Stratholme}» і поверніть їх до НІП «{npc:Betina Bigglezink}». Вам здається, що такий зразок плоті може мати будь-яка істота в підземеллі «{zone:Stratholme}».",
  ["d4abf2b6"] = "З будь-якої нежиті в підземеллі «{zone:Stratholme}» можуть випасти предмети для цього завдання.",
  ["7e15c78d"] = "Вирушайте на північ, до підземелля «{zone:Stratholme}». Обшукайте ящики з припасами, розкидані містом, і здобудьте «{item:Stratholme Holy Water}»: 5 шт. Коли зберете досить благословенної рідини, поверніться до НІП «{npc:Leonid Barthalomew the Revered}».",
  ["d11a6ef6"] = "Зберіть «{item:Stratholme Holy Water}»: 5 шт. з ящиків із припасами на вулицях; з деяких ящиків вилазять вороги.",
  ["3a29632b"] = "Знайдіть тютюнову крамницю НІП «{npc:Fras Siabi}» у підземеллі «{zone:Stratholme}» і здобудьте коробку тютюну. Коли впораєтеся, поверніться до НІП «{npc:Smokey LaRue}».",
  ["4055c389"] = "У новіших записах гри його звуть інакше. Зачистьте тютюнову крамницю, торкніться коробки з тютюном і вбийте крамаря.",
  ["b08e28c7"] = "Вирушайте до підземелля «{zone:Stratholme}» у північній частині Чумних Земель. У місцевості «{zone:The Scarlet Bastion}» ви знайдете потрібну картину, заховану за іншою картиною, на якій зображено два місяці нашого світу. Поверніть картину до НІП «{npc:Tirion Fordring}».",
  ["e538e5f8"] = "Заберіть картину, заховану за зображенням двох місяців у кімнаті боса «{npc:Archivist Galford}», перш ніж спалите архіви.",
  ["e256cc28"] = "Заберіть предмет «{item:Medallion of Faith}» у боса «{npc:Malor the Zealous}» у місцевості «{zone:The Scarlet Bastion}» і принесіть його до НІП «{npc:Aurius}».",
  ["a1abfc41"] = "Медальйон лежить у скрині біля боса в місцевості «{zone:The Scarlet Bastion}». Віддайте його НІП «{npc:Aurius}» у каплиці до бою з бароном.",
  ["cbb4cccf"] = "Знайдіть НІП «{npc:Egan}». Ви знаєте лише, що востаннє його бачили біля підземелля «{zone:Stratholme}».",
  ["0a842b7d"] = "Застосуйте предмет «{item:Egan's Blaster}» до примарних і спектральних мешканців підземелля «{zone:Stratholme}». Коли неспокійні душі вирвуться зі своїх примарних оболонок, застосуйте бластер ще раз — і вони стануть вільними! Звільніть «{npc:Restless Soul}»: 15 і поверніться до НІП «{npc:Egan}».",
  ["d9858ce0"] = "Убийте «{npc:Plaguehound Runt}»: 20, «{npc:Plaguehound}»: 5 і «{npc:Frenzied Plaguehound}»: 5. Коли впораєтеся, поверніться до НІП «{npc:Tirion Fordring}».",
  ["52ca4e1d"] = "Убийте «{npc:Plaguebat}»: 30 і поверніться до НІП «{npc:Tirion Fordring}».",
  ["ec6be8bb"] = "Розшукайте в цьому краї трупних личинок і пожирачів. Убийте їх і заберіть їхнє м’ясо. Коли зберете «{item:Slab of Carrion Worm Meat}»: 15 шт., поверніться до НІП «{npc:Tirion Fordring}».",
  ["1cf9f355"] = "Вислухайте, що скаже НІП «{npc:Tirion Fordring}».",
  ["cc77c527"] = "Вирушайте до місцевості «{zone:The Undercroft}» у найпівденнішій частині локації «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Taelan's Hammer}». Виконавши це, поверніться до НІП «{npc:Tirion Fordring}».",
  ["fddfaca7"] = "Вирушайте до місцевості «{zone:Northdale}» у північно-східній частині «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Symbol of Lost Honor}». Виконавши це, поверніться до НІП «{npc:Tirion Fordring}».",
  ["e71c0a85"] = "Вирушайте на острів «{zone:Caer Darrow}» у південно-центральній частині Чумних Земель і пошукайте будь-які підказки, де може бути картина.",
  ["c9060e87"] = "Вирушайте до підземелля «{zone:Stratholme}» і знищте боса «{npc:Baron Rivendare}». Заберіть його голову і поверніться до НІП «{npc:Duke Nicholas Zverenhoff}».",
  ["d7ec74a1"] = "Потім НІП «{npc:Lord Maxwell Tyrosus}» і «{zone:The Argent Hold}» у місцевості «{zone:Light's Hope Chapel}» дають нагороду: зброю або щит.",
  ["d5d4248b"] = "Вирушайте до підземелля «{zone:Stratholme}» і обшукайте зикурати. Знайдіть свіжий предмет «{item:Scourge Data}» і принесіть його до НІП «{npc:Betina Bigglezink}».",
  ["d0ce6884"] = "Поговоріть з НІП «{npc:Nathanos Blightcaller}» у локації «{zone:Eastern Plaguelands}». Кажуть, він оселився в місцевості «{zone:The Marris Stead}».",
  ["9c49f4df"] = "Вступний крок до завдання «{quest:Ramstein}».",
  ["80dc2e99"] = "Вирушайте до підземелля «{zone:Stratholme}» і вбийте боса «{npc:Ramstein the Gorger}». Заберіть його голову на згадку для Натаноса.",
  ["dc019211"] = "Віддайте НІП «{npc:Aurius}» предмет «{item:Medallion of Faith}»; він приєднається до бою з босом «{npc:Baron Rivendare}». Після бою заберіть у нього нагороду.",
  ["b5f5b4bf"] = "Віддайте НІП «{npc:Aurius}» предмет «{item:Medallion of Faith}» до бою з бароном; поговоріть із ним, коли бос «{npc:Baron Rivendare}» загине.",
  ["ef0a94a5"] = "Вирушайте до підземелля «{zone:Stratholme}» і врятуйте НІП «{npc:Ysida Harmon}» від боса «{npc:Baron Rivendare}».",
  ["0932c26a"] = "На час: щоб урятувати НІП «{npc:Ysida Harmon}», убийте боса «{npc:Baron Rivendare}» за 45 хвилин. Щоб побачити Антіона, використайте предмет «{item:Extra-Dimensional Ghost Revealer}».",
  ["e3a32ab9"] = "Вирушайте до підземелля «{zone:Stratholme}» і знайдіть «{zone:Menethil's Gift}». Покладіть предмет «{item:Keepsake of Remembrance}» на нечестиву землю.",
  ["451f5892"] = "Коли бос «{npc:Baron Rivendare}» загине, застосуйте сяйну руну на підлозі його кімнати, а потім поверніться з наступним завданням до Леоніда.",
  ["8e796e8f"] = "Вирушайте до локації «{zone:Arathi Highlands}», до руїн Стромґарда. Обшукайте Стромґард і знайдіть предмет «{item:Keepsake of Remembrance}». Якщо знайдете його, поверніться з ним до НІП «{npc:Magistrate Marduke}».",
  ["92fb4f6f"] = "Вирушайте до Каплиці Надії Світла в локації «{zone:Eastern Plaguelands}» і розшукайте НІП «{npc:Leonid Barthalomew the Revered}». Покажіть йому предмет «{item:Keepsake of Remembrance}» і розкажіть усе, що дізналися.",
  ["5977be67"] = "Вирушайте на схід, до місцевості «{zone:Corin's Crossing}», і перебийте ворогів, що заполонили містечко. Менш ніж за 10 хвилин зберіть «{item:Living Rot}»: 7 шт. За допомогою предмета із цього завдання розітріть «{item:Living Rot}» на предмет «{item:Coagulated Rot}».",
  ["db34934c"] = "Убийте «{npc:Noxious Plaguebat}»: 20 і «{npc:Monstrous Plaguebat}»: 10. Коли закінчите, поверніться до НІП «{npc:Nathanos Blightcaller}».",
  ["3e5122bd"] = "Вирушайте до північних кордонів локації «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Quel'Thalas Registry}». Він десь у мисливському будинку. Також убийте «{npc:Ranger}»: 8, «{npc:Pathstrider}»: 8 і «{npc:Woodsman}»: 8.",
  ["b2b5e874"] = "Знайдіть і вбийте «{npc:Duskwing}». Заберіть із тіла предмет «{item:Patch of Duskwing's Fur}» і поверніть його до НІП «{npc:Nathanos Blightcaller}». Кажуть, цей звір блукає околицями неподалік.",
  ["504b452a"] = "Знайдіть НІП «{npc:Borelgore}» у північних пустищах локації «{zone:Eastern Plaguelands}» і знищте його. Виконавши це, поверніться до НІП «{npc:Nathanos Blightcaller}».",
  ["383a526f"] = "Поверніться до підземелля «{zone:Scholomance}» з предметом «{item:Blood of Innocents}». Знайдіть ґанок і покладіть предмет «{item:Blood of Innocents}» у жаровню. Кіртонос прийде поласувати вашою душею. Бийтеся відважно, не відступайте ні на крок! Знищте Кіртоноса й поверніться до НІП «{npc:Eva Sarkhoff}».",
  ["989df5ad"] = "Використайте предмет «{item:Blood of Innocents}» біля жаровні на ґанку підземелля «{zone:Scholomance}». Нагорода — предмет «{item:Spectral Essence}».",
  ["43d211ab"] = "Знайдіть боса «{npc:Jandice Barov}» у підземеллі «{zone:Scholomance}» і знищте її. Заберіть із її тіла предмет «{item:Krastinov's Bag of Horrors}». Поверніть торбу до НІП «{npc:Eva Sarkhoff}».",
  ["97ddc342"] = "Торба випадає з боса «{npc:Jandice Barov}».",
  ["f05ba63d"] = "Знайдіть боса «{npc:Doctor Theolen Krastinov}» у підземеллі «{zone:Scholomance}». Знищте його, а тоді спаліть останки НІП «{npc:Eva Sarkhoff}» і «{npc:Lucien Sarkhoff}». Виконавши це, поверніться до НІП «{npc:Eva Sarkhoff}».",
  ["8ef12254"] = "Знайдіть боса «{npc:Ras Frostwhisper}» у підземеллі «{zone:Scholomance}». Знайшовши його, застосуйте предмет «{item:Soulbound Keepsake}» до його неживої подоби. Якщо вдасться знову зробити його смертним, убийте його і заберіть предмет «{item:Human Head of Ras Frostwhisper}». Віднесіть голову до НІП «{npc:Magistrate Marduke}».",
  ["e5c82e3a"] = "Застосуйте предмет «{item:Soulbound Keepsake}» до боса «{npc:Ras Frostwhisper}», щоб зробити його людиною, потім убийте його і принесіть його людську голову.",
  ["375ca6f4"] = "Вирушайте до підземелля «{zone:Scholomance}» і поверніть статок родини Баров. Цей статок складають чотири купчі: купча на «{zone:Caer Darrow}»; купча на «{zone:Brill}»; купча на «{zone:Tarren Mill}»; і купча на «{zone:Southshore}». Виконавши це, поверніться до НІП «{npc:Weldon Barov}».",
  ["ab602a26"] = "Чотири купчі: «{zone:Southshore}» — у першій великій залі, «{zone:Tarren Mill}» — перед дитинчатами, «{zone:Brill}» — біля боса «{npc:Ras Frostwhisper}», «{zone:Caer Darrow}» — біля боса «{npc:Lord Alexei Barov}». Наступне завдання посилає вас убити брата-суперника.",
  ["2958b5be"] = "Вирушайте до підземелля «{zone:Scholomance}» і поверніть статок родини Баров. Цей статок складають чотири купчі: купча на «{zone:Caer Darrow}»; купча на «{zone:Brill}»; купча на «{zone:Tarren Mill}»; і купча на «{zone:Southshore}». Виконавши це, поверніться до НІП «{npc:Alexi Barov}».",
  ["09d18828"] = "Покладіть предмет «{item:Dawn's Gambit}» у відповідній кімнаті підземелля «{zone:Scholomance}». Здолайте боса «{npc:Vectus}», а потім поверніться до НІП «{npc:Betina Bigglezink}».",
  ["19a4f0dc"] = "Використайте предмет «{item:Dawn's Gambit}» у місцевості «{zone:The Viewing Room}» і здолайте боса «{npc:Vectus}».",
  ["9f439b60"] = "Убийте «{npc:Plagued Hatchling}»: 20, а потім поверніться до НІП «{npc:Betina Bigglezink}» у місцевості «{zone:Light's Hope Chapel}».",
  ["fc31e3c1"] = "Убийте «{npc:Plagued Hatchling}»: 20. Після здачі цього завдання з дитинчат можуть випадати предмети: їх можна знову й знову здавати цьому НІП.",
  ["1b28f745"] = "Принесіть предмет із завдання до алхімічної лабораторії в підземеллі «{zone:Scholomance}». Коли з’явиться пергамент, поверніть банку до НІП «{npc:Gorzeeki Wildeyes}».",
  ["f54328d6"] = "Завдання чорнокнижника на скакуна жаху. Використайте предмет із завдання в алхімічній лабораторії в кімнаті боса «{npc:Ras Frostwhisper}» і дочекайтеся пергаменту.",
  ["ecfe9a86"] = "Використайте предмет «{item:Divination Scryer}» у самому серці підвалу місцевості «{zone:The Great Ossuary}» в підземеллі «{zone:Scholomance}». Так ви викличете духів, яких маєте судити. Перемога над ними викличе боса «{npc:Death Knight Darkreaver}». Здолайте його і поверніть утрачену душу полеглого бойового коня. Віддайте предмети «{item:Charger's Redeemed Soul}» і другий предмет із завдання НІП «{npc:Darkreaver's Fallen Charger}».",
  ["57133c49"] = "Завдання паладина на бойового коня. Зачистьте підвал боса «{npc:Rattlegore}» у місцевості «{zone:The Great Ossuary}», використайте предмет «{item:Divination Scryer}» і здолайте духів та боса «{npc:Death Knight Darkreaver}».",
  ["a7665b10"] = "Використайте предмет «{item:Divination Scryer}» у самому серці підвалу місцевості «{zone:The Great Ossuary}» в підземеллі «{zone:Scholomance}». Так ви викличете духів, з якими маєте битися. Перемога над ними викличе боса «{npc:Death Knight Darkreaver}»; здолайте його. Принесіть предмет «{item:Darkreaver's Head}» до НІП «{npc:Sagorne Creststrider}» у місцевості «{zone:Valley of Wisdom}» у місті «{zone:Orgrimmar}».",
  ["6f84d0a5"] = "Завдання шамана. Зачистьте підвал боса «{npc:Rattlegore}», використайте предмет із завдання і здолайте боса «{npc:Death Knight Darkreaver}»; принесіть його голову.",
  ["339931e3"] = "Поверніться до НІП «{npc:Magistrate Marduke}» у місцевості «{zone:Caer Darrow}». Покажіть йому предмет «{item:Soulbound Keepsake}».",
  ["aaaf7d3c"] = "Принесіть предмет «{item:Frozen Eggs}» до НІП «{npc:Betina Bigglezink}».",
  ["9ee56a8b"] = "Поверніться з предметом «{item:Blessed Arcanite Barding}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["7efb687b"] = "Принесіть предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["29c2fdff"] = "Якщо хочете допомогти місцевому НІП у місцевості «{zone:Valley of Wisdom}» міста «{zone:Orgrimmar}», принесіть йому предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}».",
  ["f610ec2f"] = "Принесіть до НІП «{npc:Mayena Earthseeker}» предмети «{item:Moist Crystal}», «{item:Charged Crystal}», «{item:Noxious Crystal}» і «{item:Fiery Crystal}» з підземелля «{zone:Shaper's Terrace}».",
  ["431c892c"] = "Зберіть «{item:Seeping Slime Essence}»: 8 шт. у підземеллі «{zone:Shaper's Terrace}».",
  ["cd312431"] = "Знайдіть безбарвний предмет «{item:Drained Crystal Fragment}» біля кристала у підземеллі «{zone:Shaper's Terrace}».",
  ["23131580"] = "Убийте «{npc:Ravasaur Matriarch}»: 6, залізношкурих равазаврів: 8 і ще одного НІП у підземеллі «{zone:Shaper's Terrace}».",
  ["51f9254a"] = "Знайдіть цікаві орієнтири в підземеллі «{zone:Shaper's Terrace}» і біля кожного заповніть карту дослідника: «{zone:Pillar of Assimilation}», кристал, західні ворота, «{zone:Regrowth Vestibule}» і відкопаний Кам’яний вартовий.",
  ["1f29fa1f"] = "Зберіть «{item:Partially Digested Journal Page}»: 15 шт. у підземеллі «{zone:Shaper's Terrace}».",
  ["a31fda8a"] = "Обшукайте сумку, що лежить під іншою сумкою, біля «{zone:Thoradin's Wall}».",
  ["b9864f2b"] = "Ідіть за обгорілою запискою з локації «{zone:Westfall}» до місця-двійника: обгорілих решток біля згорілої вежі на південь від «{zone:Camp Taurajo}» у локації «{zone:The Barrens}».",
  ["dcdb2e13"] = "Знайдіть затишне місце в горах між «{zone:The Barrens}» і «{zone:Desolace}»: потрібний предмет у покинутому таборі в локації «{zone:Stonetalon Mountains}».",
  ["a801f89b"] = "Підніміться стежкою на північний схід від місцевості «{zone:Sun Rock Retreat}» (50.9, 52.3) до покинутого табору; потрібний предмет лежить на ящику. За бажанням: розпаліть багаття посеред табору за допомогою предмета «{item:Simple Wood}» і предмета із цього завдання («{quest:Rekindle}»).",
  ["30ac6e8a"] = "Знайдіть орлине гніздо на стіні греблі «{zone:Stonewrought Dam}» у локації «{zone:Loch Modan}»: там лежить фігурка.",
  ["89e16b9c"] = "Щоб дістатися фігурки, стрибайте на різьблені голови греблі з боку локації «{zone:Wetlands}». Для Орди дістатися туди складно.",
  ["a7d1421e"] = "Знайдіть потрібну сумку біля «{zone:Thoradin's Wall}», між «{zone:Hillsbrad Foothills}» і «{zone:Arathi Highlands}».",
  ["9e3cb4ca"] = "Залізьте на «{zone:Thoradin's Wall}» з воза з боку «{zone:Hillsbrad}» (87.3, 49.6), пройдіть крізь кімнату в стіні й подивіться назовні праворуч: там висить торба.",
  ["28691bad"] = "Відрахуйте сто кроків точно на північ від табору і знайдіть «{zone:Mound of Dirt}» під скелею.",
  ["9e50b7e8"] = "Ідіть прямо на північ від табору, підніміться на пагорб і зістрибніть із його краю до «{zone:Mound of Dirt}». Обережно, дивіться під ноги.",
  ["e73effb2"] = "Кожен учасник рейду має мати в сумках предмет «{item:Drakefire Amulet}», щоб увійти до рейду «{zone:Onyxia's Lair}»; носити його не обов’язково. Останній крок — у підземеллі «Верхній Шпиль Блекрок»: кров боса «{npc:General Drakkisath}».",
  ["bb38ae3d"] = "Розшукайте НІП «{npc:Argent Guard Thaelrid}» у підземеллі «{zone:Blackfathom Deeps}».",
  ["89d48181"] = "Необов’язковий вступ до версії Альянсу завдання «{quest:Blackfathom Villainy}»: здайте його до того, як візьмете завдання «{quest:Blackfathom Villainy}», інакше його вже не вдасться виконати.",
  ["95d1ea21"] = "Принесіть «{item:Red Leather Bandana}»: 15 шт. НІП «{npc:Scout Galiaan}» у місцевості «{zone:Sentinel Hill}».",
  ["b986b68d"] = "Потрібне перед завданням «{quest:Red Silk Bandanas}».",
  ["7fab4322"] = "Останній крок. Нагорода — предмет «{item:Fire Hardened Hauberk}».",
  ["27cab65b"] = "Останній крок. Нагорода — предмет «{item:Verigan's Fist}».",
  ["d28bdecb"] = "Останній крок. Нагорода — предмет «{item:Brutal Hauberk}».",
  ["de37fa9a"] = "Поговоріть з НІП «{npc:Shoni the Shilent}» у місті «{zone:Stormwind}».",
  ["23635e58"] = "Веде одразу до завдання «{quest:Underground Assault}».",
  ["e48fb299"] = "Знайдіть НІП «{npc:Marvon Rivetseeker}» у локації «{zone:Tanaris}».",
  ["9c9a3641"] = "Необов’язкове вступне завдання для Альянсу, що веде до завдання «{quest:Researching the Corruption}».",
  ["41cc00c3"] = "Останній крок. НІП «{npc:Ambassador Malcin}» стоїть перед входом до підземелля «{zone:Razorfen Downs}».",
  ["6a565255"] = "Ідіть за обгорілою запискою з локації «{zone:The Barrens}» до місця-двійника: обгорілих решток на фермі «{zone:Alexston Farmstead}» у локації «{zone:Westfall}».",
  ["b0feff0a"] = "Останній крок. Виберіть один із предметів: «{item:Rage of the Storm}», «{item:Lightning's Grasp}» або «{item:Tidebringer's Claw}».",
  ["6a5aacfb"] = "Знайдіть кузню в підземеллі «{zone:Deadmines}» і закладіть поруч із нею предмет «{item:Extra-Destructive Explosives}».",
  ["e5804cd0"] = "Закладіть вибухівку біля кузні, а потім зустріньтеся з НІП «{npc:Alba Fairmoon}» біля виходу з підземелля «{zone:Deadmines}».",
  ["5a746a60"] = "Останній крок. Шукайте НІП у місцевості «{zone:The Greymane Wall}» на півдні локації «{zone:Silverpine Forest}». Нагорода — предмет.",
  ["ba3d70aa"] = "Потрібне перед завданням «{quest:Heartwoven}».",
  ["0708bdac"] = "Останній крок. Виберіть один із предметів: «{item:Rage of the Storm}», «{item:Lightning's Grasp}» або «{item:Tidebringer's Claw}»; шамани Альянсу також отримують предмет «{item:Elementalist's Guard}».",
  ["3a08ada7"] = "Попередження: приймайте це завдання лише після виконання завдання «%s», інакше те завдання буде втрачено.",
  ["cf5059d1"] = "Попередження: якщо не виконати це завдання до прийняття завдання «%s», воно стане недоступним.",
  ["90eabe36"] = "Прийміть завдання «%s» раніше за завдання «%s». Якщо завдання «%s» зникне, покиньте завдання «%s», і воно з’явиться знову.",
  ["ed541f92"] = "Убийте НІП «{npc:Qiaga the Keeper}», щоб забрати предмет «{item:Sacred Mallet}».",
  ["ce665b14"] = "«{npc:Qiaga the Keeper}» і «{npc:Morta'gya the Keeper}» — елітні вороги 50 рівня, а навколо них заклиначі; шлях до верхнього вівтаря повний тролів 45-50 рівня: візьміть групу або підкрадіться. Кожен у групі може забрати предмет «{item:Sacred Mallet}», і його можна використати в бою. Одного предмета «{item:Mallet of Zul'Farrak}» на групу досить, і він викликає боса «{npc:Gahz'rilla}» в усіх наступних проходженнях.",
  ["7f0c47fa"] = "Тут немає завдання, яке можна взяти. Просто вбийте й заберіть здобич.",
  ["0eea46c6"] ="Повторюване, після першого «{item:Medallion of Faith}».",
  ["570bcc98"] = "Використайте предмет «{item:Divination Scryer}» у центрі підвалу місцевості «{zone:The Great Ossuary}» у підземеллі «{zone:Scholomance}». З’являться духи, з якими треба битися. Здолавши їх, ви викличете боса «{npc:Death Knight Darkreaver}»; здолайте його. Принесіть предмет «{item:Darkreaver's Head}» до НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}».",
  ["97a5e99d"] = "Поговоріть із НІП «{npc:Mor'zul Bloodbringer}» у локації «{zone:Burning Steppes}».",
  ["f1cfa740"] = "Якщо хочете допомогти НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}», принесіть йому предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}».",
  ["0ec1cb7f"] = "Завдання підземелля «{zone:Maraudon}» (див. «{zone:Maraudon}»). Використайте флакон на палаючому дереві поруч із НІП «{npc:Woodwyrd}», а не на НІП «{npc:Woodwyrd}».",
  ["4c7c7f3e"] = "Знайдіть впливового свинобраза в місцевості «{zone:Bristleback Retreat}».",
}
